## Code Example

```javascript
// Pseudocode: seed events, run streaming, validate dedup and schema
async function testStreamPipeline() {
  const events = generateEvents({n: 100000, schemaVersion: 2, duplicates: true});
  await publishToMongo(events);
  const results = await collectDeltaLakeRows(loopBackoff(60s));
  assert(results.deduplicated === events.length);
  assert(results.latency < 2000);
}
```

